lient -L //mycloud -N","smbclient -L //192.168.1.XXX -N  # o per IP","","# Si tens credencials:","smbclient -L //mycloud -U bernat"],notes:["El My Cloud Home pot tenir compartits com 'Public', 'Music', 'Backup', etc.","Si demana usuari/contrasenya, s\xf3n les del compte WD.","Si no tens permisos, pot ser que hagis d'activar SMB al panell web del MyCloud (http://mycloud.local)."],verify:"Hauries de veure una llista amb 'Public', 'Music', 'SmartWare' o similar"},{id:3,title:"Crear el punt de muntatge i muntar el My Cloud",description:"Crearem una carpeta fixa al bernat-pc on el MyCloud ser\xe0 accessible, i configurarem el muntatge autom\xe0tic.",commands:["# Crear la carpeta de muntatge","sudo mkdir -p /mnt/mycloud","sudo chown bernat:bernat /mnt/mycloud","","# Muntar el compartit 'Public' (o 'Music' si existeix)","sudo mount -t cifs //mycloud/Public /mnt/mycloud \\","  -o username=bernat,password=EL_TEU_PASSWORD,uid=bernat,gid=bernat,iocharset=utf8","","# Si el compartit \xe9s 'Music'","sudo mount -t cifs //mycloud/Music /mnt/mycloud \\","  -o username=bernat,password=EL_TEU_PASSWORD,uid=bernat,gid=bernat,iocharset=utf8","","# Comprovar que s'ha muntat correctament","ls /mnt/mycloud","df -h /mnt/mycloud"],notes:["⚠️ Seguretat: escriure la contrasenya directament no \xe9s segur. Alternativa: crear un fitxer de credencials.","Per muntar sense contrasenya visible, crea /etc/samba/mycloud-credentials amb:","  username=bernat","  password=EL_TEU_PASSWORD","I fes: sudo chmod 600 /etc/samba/mycloud-credentials","Despr\xe9s munta amb -o credentials=/etc/samba/mycloud-credentials"],verify:"La comanda 'ls /mnt/mycloud' hauria de mostrar els teus fitxers"},{id:4,title:"Fer el muntatge persistent (s'arrenca autom\xe0ticament)",description:"Perqu\xe8 el MyCloud es munti cada vegada que el bernat-pc arrenqui, afegirem una entrada a fstab.",commands:["# Primer, desmuntar el muntatge temporal","sudo umount /mnt/mycloud","","# Editar fstab amb nano o vi","sudo nano /etc/fstab","","# Afegir aquesta l\xednia al final (ajusta la IP si cal):","//mycloud/Public  /mnt/mycloud  cifs  credentials=/etc/samba/mycloud-credentials,uid=bernat,gid=bernat,iocharset=utf8,_netdev,x-systemd.automount,x-systemd.requires=network-online.target  0  0","","# Si no tens fitxer de credencials, pots fer-ho menys segur amb:","//mycloud/Public  /mnt/mycloud  cifs  username=bernat,password=EL_TEU_PASSWORD,uid=bernat,gid=bernat,iocharset=utf8,_netdev  0  0","","# Provar que fstab funciona sense reiniciar","sudo mount -a","ls /mnt/mycloud"],notes:["Les opcions _netdev i x-systemd.* asseguren que el muntatge esperi a tenir xarxa.","Si el bernat-pc arrenca sense xarxa, pot trigar una mica a muntar.","Per depurar: sudo mount -v -t cifs //mycloud/Public /mnt/mycloud"],verify:"Despr\xe9s de 'sudo mount -a', el muntatge ha d'apar\xe8ixer a 'df -h'"},{id:5,title:"Copiar la m\xfasica al projecte o enlla\xe7ar-la",description:"Un cop muntat, pots triar entre copiar la m\xfasica (consumeix espai al disc del bernat-pc) o fer-la accessible via enlla\xe7 simb\xf2lic (estalvia espai per\xf2 cal que el MyCloud estigui sempre enc\xe8s).",commands:["### OPCI\xd3 A: Copiar la m\xfasica (recomanada per rendiment) ###","","# Copiar tot el que tens a OneDrive des del MyCloud","rsync -av --progress /mnt/mycloud/Musica/ ~/jazz-fusion-guitar/public/library/audio/","","# Copiar PDFs","rsync -av --progress /mnt/mycloud/Documents/ ~/jazz-fusion-guitar/public/library/documents/","","### OPCI\xd3 B: Enlla\xe7 simb\xf2lic (estalvia espai) ###","","# Esborrar la carpeta de l'app i fer un symlink","rmdir ~/jazz-fusion-guitar/public/library/audio 2>/dev/null","ln -s /mnt/mycloud/Musica ~/jazz-fusion-guitar/public/library/audio","","### Comprovar l'estructura ###","ls -la ~/jazz-fusion-guitar/public/library/","ls /mnt/mycloud | head -20"],notes:["Opci\xf3 A: M\xe9s r\xe0pid, per\xf2 duplica dades. Recomanat si tens espai al disc.","Opci\xf3 B: Estalvia espai, per\xf2 el bernat-pc necessita el MyCloud enc\xe8s per servir fitxers.","Pots fer una barreja: copiar Creative Intervallic (113 MB) i enlla\xe7ar la resta."],verify:"Els fitxers han de ser visibles a ~/jazz-fusion-guitar/public/library/"},{id:6,title:"Crear les p\xe0gines noves a l'app",description:"Un cop els fitxers s\xf3n accessibles, podem crear p\xe0gines dedicades per cada categoria (PDFs, tabs, \xe0udio) amb visors i reproductors integrats.",commands:["# Reiniciar l'aplicaci\xf3 per recarregar la nova estructura","jfg restart","","# Verificar que tot funciona","jfg test","","# Comprovar rutes espec\xedfiques","curl -I http://localhost:3000/biblioteca"],notes:["Quan tinguis els fitxers al lloc, avisa'm i creo les p\xe0gines noves:","  - /biblioteca/pdfs → visor PDF integrat amb cerca","  - /biblioteca/blues-jazz → reproductor d'\xe0udio per carpetes","  - /biblioteca/tabs → \xedndex de Guitar Pro Tabs (10k+) amb filtres","  - /biblioteca/country → similar per a la secci\xf3 country","","Si hi ha molts PDFs o tabs, podem afegir un sistema d'\xedndex amb cerca r\xe0pida."],verify:"Les p\xe0gines han de carregar sense errors 404"}];function b(){let[e,r]=(0,s.useState)(new Set),[a,l]=(0,s.useState)(1);return(0,t.jsxs)(t.Fragment,{children:[(0,t.jsxs)("section",{className:"page-header",children:[(0,t.jsxs)("div",{style:{display:"flex",alignItems:"center",gap:"0.75rem",marginBottom:"1rem"},children:[(0,t.jsx)(i.A,{size:32,color:"var(--accent-amber)"}),(0,t.jsx)("h1",{style:{margin:0},children:"Configurar My Cloud Home"})]}),(0,t.jsxs)("p",{children:["Guia pas a pas per connectar el ",(0,t.jsx)("strong",{children:"WD My Cloud Home"})," al bernat-pc i fer accessible tota la teva col\xb7lecci\xf3 de m\xfasica des de l'aplicaci\xf3 Jazz Fusion Guitar."]})]}),(0,t.jsxs)("section",{className:"section",style:{paddingTop:0},children:[(0,t.jsxs)("div",{className:"card",style:{marginBottom:"1.5rem",background:"linear-gradient(135deg, var(--bg-card), var(--bg-tertiary))"},children:[(0,t.jsxs)("h2",{style:{display:"flex",ali